actions.script:
def course = c ? ec.entity.find("growerp.course.Course").condition("courseId", c)
    .disableAuthz().one() : null
String location = course?.coverImageUrl?.startsWith('/courseMedia/cover') ?
    "dbresource://C${course.ownerPartyId}/courses/${c}/cover.png" : null
if (!location) { ec.web.sendError(404, null, null); return }
ec.web.sendResourceResponse(location, true)

import jakarta.servlet.http.HttpServletResponse

HttpServletResponse response = ec.web.response
def module = t ? ec.entity.find("growerp.course.CourseModule").condition("videoToken", t)
    .disableAuthz().one() : null
def reference = module?.videoLocation ? ec.resource.getLocationReference(module.videoLocation) : null
byte[] data = reference?.openStream()?.withCloseable { it.readAllBytes() }
if (!data) {
    response.sendError(HttpServletResponse.SC_NOT_FOUND)
    return
}
long length = data.length
long start = 0, end = length - 1
String range = ec.web.request.getHeader("Range")
def matcher = range =~ /^bytes=(\d*)-(\d*)$/
if (matcher.matches()) {
    if (matcher.group(1)) {
        start = matcher.group(1) as long
        if (matcher.group(2)) end = Math.min(matcher.group(2) as long, length - 1)
    } else if (matcher.group(2)) {
        // suffix range: the last n bytes
        start = Math.max(0L, length - (matcher.group(2) as long))
    }
    if (start > end || start >= length) {
        response.setHeader("Content-Range", "bytes */${length}")
        response.sendError(HttpServletResponse.SC_REQUESTED_RANGE_NOT_SATISFIABLE)
        return
    }
    response.status = HttpServletResponse.SC_PARTIAL_CONTENT
    response.setHeader("Content-Range", "bytes ${start}-${end}/${length}")
}
response.contentType = "video/mp4"
response.setHeader("Accept-Ranges", "bytes")
response.setHeader("Cache-Control", "private, max-age=86400")
response.setContentLengthLong(end - start + 1)
response.outputStream.write(data, (int) start, (int) (end - start + 1))
response.outputStream.flush()
